"use client";

import { ArrowRight, ShoppingBag } from "lucide-react";
import Link from "next/link";
import { ROUTES } from "@/constants/navigation";
import { cn } from "@/lib/utils";

export interface ProductInquiryInfo {
  title: string;
  price?: string;
  isAvailableQuestion: boolean;
}

/**
 * Detects if a chat message is inquiring about or referencing a marketplace item.
 * Supports patterns generated by "Contact Seller" buttons:
 * - `is "Title" (₹2,800) still available?`
 * - `is "Title" (Rs. 2,800) still available?`
 * - `"Title" (₹2,800)`
 */
export function parseMarketplaceInquiry(text: string): ProductInquiryInfo | null {
  if (!text) return null;

  // 1. Matches automated seller inquiry:
  // "Hi @user, is "Item Title" (₹2,800) still available?"
  const inquiryRegex =
    /is\s+["“](.+?)["”]\s*(?:\((?:₹|Rs\.?|INR)?\s*([\d,]+)\))?\s*still\s*available(?:\s+on\s+campusloop)?\??/i;
  const inquiryMatch = text.match(inquiryRegex);
  if (inquiryMatch) {
    return {
      title: inquiryMatch[1].trim(),
      price: inquiryMatch[2] ? `₹${inquiryMatch[2].trim()}` : undefined,
      isAvailableQuestion: true,
    };
  }

  // 2. Matches quoted item with price tag:
  // "Item Title" (₹2,800)
  const quotedRegex = /["“](.+?)["”]\s*\((?:₹|Rs\.?|INR)\s*([\d,]+)\)/i;
  const quotedMatch = text.match(quotedRegex);
  if (quotedMatch) {
    return {
      title: quotedMatch[1].trim(),
      price: `₹${quotedMatch[2].trim()}`,
      isAvailableQuestion: false,
    };
  }

  return null;
}

interface ProductMessageCardProps {
  product: ProductInquiryInfo;
  isMe: boolean;
}

export function ProductMessageCard({ product, isMe }: ProductMessageCardProps) {
  return (
    <div
      className={cn(
        "my-1.5 space-y-1.5 rounded-md border bg-surface p-3 text-left text-fg select-none",
        isMe ? "border-transparent" : "border-border"
      )}
    >
      <div className="flex items-center gap-1.5 text-xs font-medium text-fg-muted">
        <ShoppingBag className="size-3.5 shrink-0 text-brand-text" aria-hidden="true" />
        <span>{product.isAvailableQuestion ? "Asking about a listing" : "Listing"}</span>
      </div>
      <p className="line-clamp-2 text-sm leading-snug font-semibold">{product.title}</p>
      {product.price && <p className="text-sm font-bold tabular-nums">{product.price}</p>}
      <Link
        href={ROUTES.buySell}
        onClick={(e) => e.stopPropagation()}
        className="inline-flex min-h-8 items-center gap-1 text-sm font-medium text-brand-text underline-offset-2 hover:underline"
      >
        Open Buy and sell
        <ArrowRight className="size-3.5" aria-hidden="true" />
      </Link>
    </div>
  );
}
